import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { api, download, setCSRF, streamEvents } from './api';
import { ProjectControls, ModelPresetControls, ExecutionSettings, TraceRegister, RetestControl, ROLE_LABELS, defaultExtensions } from './extensions';
import type { AuthProfile, Budget, Capabilities, Finding, ModelProfile, Provider, Run, RunInput, RunExtensions, Session, TestCase } from './types';

const STAGES = [['intake','接收'],['preflight','預檢'],['whitebox','白箱審查'],['adjudication','證據仲裁'],['threat_model','威脅建模'],['case_design','測試設計'],['blackbox','黑箱驗證'],['report','產出報告'],['complete','完成']];
const STATUS: Record<string,string> = {created:'待啟動',running:'執行中',cancelling:'停止中',cancelled:'已停止',completed:'已完成',complete:'已完成',sealed:'初審已封存',incomplete:'未完整完成',blocked:'受阻',failed:'執行失敗',pass:'未觀測到違規',fail:'觀測到違規',inconclusive:'證據不足',execution_error:'執行錯誤',outcome_unknown:'結果不明'};
const STATES: Record<string,string> = {hypothesis:'待驗證假設',corroborated_static:'靜態佐證',validated_dynamic:'動態驗證',refuted:'已排除',inconclusive:'尚無定論'};
const SEVERITY: Record<string,string> = {critical:'嚴重',high:'高',medium:'中',low:'低',info:'資訊'};
const PROVIDERS: Record<Provider,string> = {demo:'本地合成示範',openai:'OpenAI',anthropic:'Anthropic Claude',nvidia_nim:'NVIDIA NIM',openai_compatible:'相容 API／本地模型'};
const formatNumber = (n: number | undefined) => new Intl.NumberFormat('zh-TW').format(n ?? 0);
const short = (text: string | undefined) => text ? `${text.slice(0,10)}${text.length > 10 ? '…' : ''}` : '未記錄';
const date = (value: string) => { const d = new Date(value); return Number.isNaN(d.getTime()) ? value : d.toLocaleString('zh-TW', {month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}); };
const stringify = (v: unknown): string => typeof v === 'string' ? v : JSON.stringify(v,null,2) ?? '—';
function record(value: unknown): Record<string,unknown> { return value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Record<string,unknown> : {}; }
function executionResult(ex: Record<string,unknown>) { return Object.keys(record(ex.result)).length ? record(ex.result) : ex; }
function Icon({name,size=20}: {name:string;size?:number}) {
  const paths: Record<string,ReactNode> = {
    shield:<><path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/><path d="m8 12 3 3 5-6"/></>,
    grid:<><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></>,
    plus:<path d="M12 5v14M5 12h14"/>, play:<path d="m8 4 12 8-12 8Z"/>, stop:<rect x="5" y="5" width="14" height="14" rx="2"/>,
    arrow:<path d="M5 12h14m-5-5 5 5-5 5"/>, check:<path d="m5 12 4 4L19 6"/>, refresh:<><path d="M20 11a8 8 0 0 0-14-5L3 9m0-5v5h5M4 13a8 8 0 0 0 14 5l3-3m0 5v-5h-5"/></>,
    chip:<><rect x="6" y="6" width="12" height="12" rx="3"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 3v3m6-3v3m-6 12v3m6-3v3M3 9h3m-3 6h3m12-6h3m-3 6h3"/></>,
    lock:<><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></>,
    file:<><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9Z"/><path d="M14 3v6h6M8 13h8m-8 4h5"/></>,
    pulse:<path d="M2 12h5l3-8 4 16 3-8h5"/>, download:<><path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/></>,
    alert:<><path d="m12 3 10 18H2Z"/><path d="M12 9v5m0 3v.2"/></>, link:<><path d="m9 15 6-6m-7 3-2 2a4 4 0 0 0 6 6l2-2m-4-12 2-2a4 4 0 0 1 6 6l-2 2"/></>,
    code:<><path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-16-2 20"/></>, close:<path d="m6 6 12 12M6 18 18 6"/>, chevron:<path d="m9 5 7 7-7 7"/>,
  };
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name] ?? paths.file}</svg>;
}
function Badge({value,children}: {value?:string;children?:ReactNode}) { return <span className={`badge ${value ?? ''}`}>{children ?? STATUS[value ?? ''] ?? value}</span>; }
function Empty({title,children}: {title:string;children?:ReactNode}) { return <div className="empty"><span className="empty-icon"><Icon name="file" size={25}/></span><h3>{title}</h3><p>{children}</p></div>; }
function SafeText({value}: {value:unknown}) { return <pre className="safe-text">{stringify(value)}</pre>; }
function Panel({title,eyebrow,children,action}: {title:string;eyebrow?:string;children:ReactNode;action?:ReactNode}) { return <section className="panel"><div className="panel-heading"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{action}</div>{children}</section>; }

export default function App() {
  const [session,setSession] = useState<Session|null>(null);
  const [capabilities,setCapabilities] = useState<Capabilities|null>(null);
  const [runs,setRuns] = useState<Run[]>([]);
  const [selected,setSelected] = useState<Run|null>(null);
  const [view,setView] = useState<'runs'|'create'|'capabilities'>('runs');
  const [tab,setTab] = useState('overview');
  const [error,setError] = useState('');
  const [busy,setBusy] = useState('');
  const [connecting,setConnecting] = useState(true);
  const syncRun = useCallback((run:Run) => {setSelected(run); setRuns(prev => [run,...prev.filter(r=>r.id!==run.id)]);},[]);
  const connect = useCallback(async () => {
    setConnecting(true); setError('');
    try {
      const s = await api<Session>('/session'); setCSRF(s.csrf_token); setSession(s);
      const [caps,list] = await Promise.all([api<Capabilities>('/capabilities'),api<{runs:Run[]}>('/runs')]);
      setCapabilities(caps); setRuns(list.runs);
      if (list.runs.length) setSelected(await api<Run>(`/runs/${encodeURIComponent(list.runs[0].id)}`));
    } catch (e) {setError(e instanceof Error ? e.message : '無法連線至本地服務');}
    finally {setConnecting(false);}
  },[]);
  useEffect(()=>{void connect();},[connect]);
  useEffect(()=>{
    if (!selected || !['running','cancelling'].includes(selected.status)) return;
    let active = true;
    let fetching = false;
    const refresh = async () => {
      if (fetching) return; fetching = true;
      try { const run = await api<Run>(`/runs/${encodeURIComponent(selected.id)}`); if(active) syncRun(run); }
      catch(e) { if(active) setError(`更新中斷：${e instanceof Error?e.message:'連線失敗'}。重新連線後可查看已保存進度。`); }
      finally {fetching = false;}
    };
    const stream = new AbortController();
    // Polling below keeps the view current if the event stream drops.
    streamEvents(`/runs/${encodeURIComponent(selected.id)}/events`,name=>{void refresh();if(name==='done')stream.abort();},stream.signal).catch(()=>{});
    const timer = window.setInterval(refresh,2500);
    return ()=>{active=false;clearInterval(timer);stream.abort();};
  },[selected?.id,selected?.status,syncRun]);
  async function selectRun(run:Run) {setBusy('load');setError('');try {syncRun(await api<Run>(`/runs/${encodeURIComponent(run.id)}`));setView('runs');setTab('overview');}catch(e){setError(String(e));}finally{setBusy('');}}
  async function action(kind:RunAction) {if(!selected)return;let body={};if(kind==='reconcile'){const attestation=window.prompt('監督程式未能確認工作容器已移除。請說明你如何確認已清理或重設測試環境。這段說明會存為證據；此執行之後不能再恢復，請以新的執行繼續。')?.trim();if(!attestation)return;body={attestation};}setBusy(kind);setError('');try {syncRun(await api<Run>(`/runs/${encodeURIComponent(selected.id)}/${kind}`,body));}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy('');}}
  async function createRun(input:RunInput) {
    setBusy('create');setError('');
    try {const run=await api<Run>('/runs',input);syncRun(run);setView('runs');setTab('overview');syncRun(await api<Run>(`/runs/${encodeURIComponent(run.id)}/start`,{}));}
    catch(e){setError(e instanceof Error?e.message:String(e));throw e;}
    finally{setBusy('');}
  }
  return <div className="app-shell">
    <aside className="sidebar">
      <a className="brand" href="#" onClick={e=>{e.preventDefault();setView('runs');}}><span className="brand-mark"><Icon name="shield" size={25}/></span><span>Vibe Audit<small>安全驗證工作台</small></span><span className="version">α</span></a>
      <div className="workspace-tag"><span className="live-dot"/> LOCAL WORKSPACE</div>
      <nav aria-label="主要導覽"><button className={view==='runs'?'nav active':'nav'} onClick={()=>setView('runs')}><Icon name="grid"/>評估工作台<span className="nav-count">{runs.length}</span></button><button className={view==='create'?'nav active':'nav'} onClick={()=>setView('create')}><Icon name="plus"/>新建評估</button><button className={view==='capabilities'?'nav active':'nav'} onClick={()=>setView('capabilities')}><Icon name="chip"/>工具與執行環境</button></nav>
      <div className="sidebar-label">最近的評估</div>
      <div className="recent-list">{runs.slice(0,8).map(run=><button key={run.id} className={`recent ${selected?.id===run.id&&view==='runs'?'selected':''}`} onClick={()=>void selectRun(run)}><span className={`status-dot ${run.status}`}/><span className="recent-content"><strong>{run.name}</strong><small>{run.mode==='demo'?'示範':'實際評估'} · {date(run.created_at)}</small></span></button>)}{!runs.length&&<p className="sidebar-empty">每一次評估，都留下<br/>可追溯的證據。</p>}</div>
      <div className="sidebar-footer"><Icon name="lock" size={17}/><span>執行於本機<small>資料送往模型依你的設定</small></span></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb">工作空間 <Icon name="chevron" size={13}/><strong>{view==='create'?'新建評估':view==='capabilities'?'工具與執行環境':'評估工作台'}</strong></div><div className="topbar-status"><span className={session?'live-dot':'live-dot off'}/>{connecting?'連線中':session?'本地服務已連線':'服務未連線'}<button className="icon-button" aria-label="重新連線並更新" title="重新連線並更新" onClick={()=>void connect()} disabled={connecting}><Icon name="refresh" size={16}/></button></div></header>
      <main>
        {error&&<div className="notice error" role="alert"><Icon name="alert"/><div><strong>這次操作尚未完成</strong><p>{error}</p></div><button className="icon-button" aria-label="關閉提示" onClick={()=>setError('')}><Icon name="close" size={16}/></button></div>}
        {!session&&!connecting?<div className="connection-card"><Icon name="pulse" size={38}/><h1>等待本地服務</h1><p>先啟動 Vibe Audit 後端，並開啟它在終端機印出的含權杖網址。評估與證據會保存在你的本地工作空間。</p><button className="button primary" onClick={()=>void connect()}><Icon name="refresh" size={17}/>重新連線</button><code>API · {import.meta.env.DEV?'127.0.0.1:8000（開發模式經 Vite 代理）':window.location.host||'本機服務'}</code></div>:view==='create'?<CreateForm onCreate={createRun} busy={busy==='create'} connected={!!session}/>:view==='capabilities'?<CapabilitiesView capabilities={capabilities} session={session}/>:<>
          <div className="page-heading"><div><div className="eyebrow">EVIDENCE BEFORE CONFIDENCE</div><h1>{selected?selected.name:'讓安全，有跡可循。'}</h1><p>{selected?'從獨立白箱審查，到威脅導向驗證。每個結論都連回證據。':'先讀懂程式，再建立威脅模型，最後驗證真正的風險。'}</p></div><button className="button primary" onClick={()=>setView('create')}><Icon name="plus" size={18}/>新建評估</button></div>
          {selected?<RunDetail run={selected} tab={tab} setTab={setTab} action={action} busy={busy} onCreated={syncRun}/>:<><div className="welcome-grid"><div className="welcome-main"><div className="orbit-graphic"><span className="orbit o1"/><span className="orbit o2"/><span className="orbit o3"/><span className="center-shield"><Icon name="shield" size={42}/></span><span className="orbit-node n1"><Icon name="code" size={18}/></span><span className="orbit-node n2"><Icon name="chip" size={18}/></span><span className="orbit-node n3"><Icon name="file" size={18}/></span></div><span className="eyebrow">MULTI-MODEL · LOCAL-FIRST</span><h2>不同模型，獨立思考。<br/>共同依據，是證據。</h2><p>一位指揮官協調三位審查員。各自完成初審後，再彙整工具結果與歧見，將威脅逐一轉為可驗證的測試。</p><button className="button primary" onClick={()=>setView('create')}>開始第一個評估<Icon name="arrow" size={17}/></button></div><div className="welcome-steps">{[['01','獨立白箱審查','在同一份程式快照上，保留每個模型的判斷。','code'],['02','威脅模型先行','記錄資產、信任邊界與應被維持的安全條件。','shield'],['03','用實際觀測驗證','案例、執行與發現串成一條完整證據鏈。','link']].map(([n,title,desc,icon])=><div className="welcome-step" key={n}><span className="step-number">{n}</span><Icon name={icon}/><h3>{title}</h3><p>{desc}</p></div>)}</div></div><div className="notice subtle"><Icon name="file"/><p>第一次使用？新建評估中的「合成示範」會在本地執行完整流程，不需模型金鑰，也不會對外發送測試請求。</p></div></>}
        </>}
      </main><footer className="main-footer"><span>VIBE AUDIT / LOCAL SECURITY WORKBENCH</span><span>未發現違規 ≠ 已證明安全</span></footer>
    </div>
  </div>;
}

// Mirrors the backend's resume refusals, so the console never offers a resume that cannot succeed.
const resumable=(run:Run)=>!run.workers_pending_cleanup&&!run.usage_unknown&&!run.deployment_changed&&!run.executions.some(e=>e.status==='outcome_unknown'||e.target_state_confirmed===false);
const REPORT_FORMATS = [['markdown','Markdown','md'],['json','完整 JSON','json'],['sarif','SARIF','sarif']] as const;
function ReportMenu({run}: {run:Run}) {
  const [error,setError] = useState('');
  async function save(format:string,extension:string) {setError('');try {await download(`/runs/${encodeURIComponent(run.id)}/report?format=${format}`,`vibe-audit-${run.id.slice(0,8)}.${extension}`);}catch(e){setError(`匯出失敗：${e instanceof Error?e.message:String(e)}`);}}
  return <details className="download-menu"><summary className="button secondary small"><Icon name="download" size={15}/>匯出報告</summary><div>{REPORT_FORMATS.map(([format,label,extension])=><button type="button" key={format} onClick={()=>void save(format,extension)}>{label}<Icon name="download" size={13}/></button>)}{error&&<p className="download-error" role="alert">{error}</p>}</div></details>;
}
type RunAction = 'start'|'cancel'|'resume'|'reconcile';
function RunDetail({run,tab,setTab,action,busy,onCreated}: {run:Run;tab:string;setTab:(tab:string)=>void;action:(kind:RunAction)=>Promise<void>;busy:string;onCreated?:(run:Run)=>void}) {
  const [focusEvidence,setFocusEvidence]=useState('');
  const stageIndex=STAGES.findIndex(([id])=>id===run.stage);
  const findings=run.findings??[];
  const threats=run.threat_model?.threats??[];
  const dynamic=findings.filter(f=>f.state==='validated_dynamic').length;
  const events=run.events??[];
  return <>
    <div className={`run-banner ${run.mode}`}><div><span className="banner-icon"><Icon name={run.mode==='demo'?'chip':'lock'} size={20}/></span><div><strong>{run.mode==='demo'?'合成示範 · 不是實際安全評估':'實際評估 · 僅在設定範圍內執行'}</strong><p>{run.mode==='demo'?'結果來自本地合成情境；沒有呼叫真實 LLM，也不代表任何模型的偵測能力。':run.manifest.data_policy==='local_only'?'模型請求限本地端點；測試僅前往已設定的隔離環境。':'已允許雲端模型；程式內容可能送往你明確允許的模型端點。'}</p></div></div><Badge value={run.status}/></div>
    <div className="run-toolbar"><div className="run-meta"><span><Icon name="file" size={14}/><code>{short(run.id)}</code></span><span>建立於 {date(run.created_at)}</span>{run.manifest.deployment_id&&<span>部署 <code>{run.manifest.deployment_id}</code></span>}</div><div className="toolbar-actions"><RetestControl key={run.id} run={run} onCreated={onCreated}/>{run.status==='created'&&<button className="button primary small" disabled={!!busy} onClick={()=>void action('start')}><Icon name="play" size={14}/>啟動</button>}{['running','cancelling'].includes(run.status)&&<button className="button danger small" disabled={!!busy||run.status==='cancelling'} onClick={()=>void action('cancel')}><Icon name="stop" size={14}/>{run.status==='cancelling'?'停止中':'停止執行'}</button>}{run.status==='cancelling'&&run.workers_pending_cleanup&&<button className="button secondary small" disabled={!!busy} onClick={()=>void action('reconcile')}><Icon name="check" size={14}/>確認已清理</button>}{['cancelled','incomplete','failed','blocked'].includes(run.status)&&(resumable(run)?<button className="button secondary small" disabled={!!busy} onClick={()=>void action('resume')}><Icon name="refresh" size={14}/>嘗試恢復</button>:<span className="resume-note" title="有未確認的副作用、清理、用量或部署變更；請重設環境後建立新的執行">需建立新的執行</span>)}<ReportMenu run={run}/></div></div>
    <section className="stage-panel" aria-label="評估階段"><div className="stage-top"><span className="eyebrow">ASSESSMENT PIPELINE</span><span>{Math.max(0,stageIndex)+1} / {STAGES.length} 階段</span></div><ol className="stage-list">{STAGES.map(([id,label],i)=>{const done=i<stageIndex||(run.status==='completed'&&i===stageIndex);return <li key={id} className={`${done?'done':''} ${i===stageIndex?'current':''}`} aria-current={i===stageIndex?'step':undefined}><span className="stage-circle">{done?<Icon name="check" size={14}/>:String(i+1).padStart(2,'0')}</span><span>{label}</span></li>;})}</ol></section>
    <div className="metrics-grid"><Metric title="安全發現" value={findings.length} note={`${dynamic} 項具動態驗證`} icon="shield"/><Metric title="威脅情境" value={threats.length} note={`${run.threat_model?.assets?.length??0} 項資產`} icon="link"/><Metric title="測試案例" value={run.cases?.length??0} note={`${run.executions?.length??0} 筆執行紀錄`} icon="code"/><Metric title="驗證缺口" value={run.gaps?.length??0} note="未驗證項目明確保留" icon="alert" warn={!!run.gaps?.length}/></div>
    <div className="tabs" role="tablist" aria-label="評估內容">{[['overview','總覽與模型'],['trace','威脅與測試'],['findings',`發現 (${findings.length})`],['evidence','執行與證據'],['activity','執行紀錄']].map(([id,label])=><button id={`tab-${id}`} role="tab" aria-selected={tab===id} aria-controls="tab-panel" key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>
    <div id="tab-panel" role="tabpanel" aria-labelledby={`tab-${tab}`}>
      {tab==='overview'&&<div className="detail-columns"><div><Panel title="獨立審查小組" eyebrow="MODEL ATTRIBUTION"><div className="agent-list">{run.manifest.models.map((model,i)=>{const review=run.reviews?.find(r=>r.agent_id===model.id);return <div className="agent-row" key={model.id}><span className={`agent-avatar a${i}`}><Icon name={i===0?'shield':'chip'} size={21}/></span><div className="agent-info"><strong>{ROLE_LABELS[model.role]}<code>{model.id}</code></strong><span>{model.provider==='demo'?'合成示範':PROVIDERS[model.provider]} · {model.model_id||'未設定'}</span><small>模型家族 {model.family||'未設定'}{review?.input_hash?` · 輸入 ${short(review.input_hash)}`:''}</small></div><div className="agent-result">{review?<><Badge value={review.status}/><small>{review.findings.length} 項候選{review.simulated?' · 合成':''}</small></>:<span className="muted">{model.role==='commander'?'協調流程':'尚無審查結果'}</span>}</div></div>;})}</div><div className="panel-footnote">初審先封存，再進行證據仲裁。模型同意的數量不等於漏洞成立。</div></Panel><Panel title="評估範圍" eyebrow="IMMUTABLE CONTEXT"><dl className="context-list"><dt>來源</dt><dd>{run.manifest.source_path||'本地合成 fixture'}</dd><dt>目標</dt><dd>{run.manifest.target_url||'示範不對外連線'}</dd><dt>來源摘要</dt><dd><code>{run.threat_model?.source_digest||'尚未建立'}</code></dd><dt>威脅模型摘要</dt><dd><code>{run.threat_model?.hash||'尚未建立'}</code></dd><dt>資料政策</dt><dd>{run.manifest.data_policy==='local_only'?'僅本地模型':'允許指定雲端模型'}</dd><dt>備註</dt><dd>{run.manifest.notes||'—'}</dd></dl></Panel></div><div><Panel title="資源使用量" eyebrow="RUN BUDGET"><Usage label="目標請求" used={run.usage?.requests} max={run.manifest.budget.max_requests}/><Usage label="模型呼叫" used={run.usage?.model_calls} max={run.manifest.budget.max_model_calls}/><Usage label="Tokens" used={run.usage?.tokens} max={run.manifest.budget.max_tokens}/><div className="budget-time"><Icon name="pulse" size={15}/>時間上限 {formatNumber(run.manifest.budget.max_seconds)} 秒</div></Panel><Panel title="驗證缺口" eyebrow="KNOWN UNKNOWNS">{run.gaps?.length?<div className="gaps-list">{run.gaps.map((gap,i)=><div className="gap" key={i}><Icon name="alert" size={16}/><SafeText value={gap}/></div>)}</div>:<p className="panel-copy">目前沒有已記錄的缺口。這不代表評估已完成，也不表示系統沒有風險。</p>}</Panel>{run.limitations?.length?<Panel title="能力限制"><SafeText value={run.limitations}/></Panel>:null}{run.error!=null&&<Panel title="執行問題"><SafeText value={run.error}/></Panel>}</div></div>}
      {tab==='trace'&&<><div className="section-intro"><Icon name="link"/><div><h2>從安全條件，追到實際觀測</h2><p>每項威脅對應案例與結果；尚未執行或缺少必要觀測時，保留未確認狀態。</p></div></div>{threats.length?threats.map(threat=><article className="threat-card" key={threat.id}><div className="threat-header"><div className="trace-id">{threat.id}</div><div><h3>{threat.title}</h3><span className="muted">{threat.category} · {threat.requirement_id}</span></div><Badge value={threat.testability==='blocked'?'blocked':'info'}>{threat.testability==='blocked'?'尚不可自動驗證':'可自動驗證'}</Badge></div><div className="invariant"><span>應維持的安全條件</span><p>{threat.invariant}</p></div>{threat.blocked_reason&&<p className="inline-warning">{threat.blocked_reason}</p>}<div className="trace-cases">{run.cases.filter(c=>c.threat_ids.includes(threat.id)).map(c=><CaseCard key={c.id} testCase={c} executions={run.executions.filter(e=>e.case_id===c.id)}/>)}{!run.cases.some(c=>c.threat_ids.includes(threat.id))&&<div className="trace-empty">尚無對應案例</div>}</div><details className="text-details"><summary>檢視資產、假設與控制證據</summary><SafeText value={{asset_ids:threat.asset_ids,preconditions:threat.preconditions,assumptions:threat.assumptions,control_evidence:threat.control_evidence,impact:threat.impact}}/></details></article>):<Empty title="威脅模型尚未建立">完成白箱審查與仲裁後，系統才會建立威脅模型並設計測試。</Empty>}{run.cases.filter(c=>!c.threat_ids.some(id=>threats.some(t=>t.id===id))).map(c=><CaseCard key={c.id} testCase={c} executions={run.executions.filter(e=>e.case_id===c.id)}/>)}</>}
      {tab==='trace'&&<TraceRegister run={run}/>}
      {tab==='findings'&&<Findings run={run} onEvidence={id=>{setFocusEvidence(id);setTab('evidence');}} onUpdated={onCreated}/>}
      {tab==='evidence'&&<><div className="notice subtle"><Icon name="lock"/><p>證據以純文字顯示，不執行目標回傳的 HTML 或腳本。Trace 是額外觀測，不等同已發生的外部工具副作用。</p></div>{run.executions?.length?run.executions.map((ex,i)=>{const result=executionResult(ex);return <article className="execution-card" key={String(ex.id??i)}><div className="execution-header"><div><span className="eyebrow">EXECUTION {String(i+1).padStart(2,'0')}</span><h3>{String(ex.case_id??ex.id??'未記錄案例識別')}</h3></div><Badge value={String(result.status??'inconclusive')}/></div><p>{String(result.reason??'未提供判定說明')}</p><div className="execution-meta"><span>{result.requests==null?'請求次數未知（結果不明，未確認是否已送達）':`${formatNumber(Number(result.requests))} 次請求`}</span><span>{String(ex.observation_mode??run.cases.find(c=>c.id===ex.case_id)?.observation_mode??'未記錄觀測模式')}</span></div><details className="text-details"><summary>觀測紀錄</summary><SafeText value={result.observations??[]}/></details><details className="text-details"><summary>原始證據與關聯識別</summary><SafeText value={ex}/></details></article>;}):<Empty title="尚無動態執行證據">威脅模型與測試案例通過閘門後，才會對設定的目標進行驗證。</Empty>}</>}
      {tab==='evidence'&&<EvidenceBrowser key={run.id} run={run} focusId={focusEvidence}/>}
      {tab==='activity'&&<Panel title="完整執行紀錄" eyebrow="AUDIT TRAIL" action={<span className="muted">{events.length} 筆事件</span>}>{events.length?<ol className="event-list">{events.map((e,i)=><li key={`${e.seq}-${i}`} className={e.level}><time>{date(e.at)}</time><span className="event-dot"/><div><div className="event-label"><strong>{STAGES.find(([id])=>id===e.stage)?.[1]??e.stage}</strong>{e.agent_id&&<code>{e.agent_id}</code>}<small>#{e.seq}</small></div><p>{e.message}</p></div></li>)}</ol>:<Empty title="等待第一筆事件">啟動評估後，進度會自動更新。</Empty>}</Panel>}
    </div>
  </>;
}
function Metric({title,value,note,icon,warn=false}: {title:string;value:number;note:string;icon:string;warn?:boolean}) {return <div className={`metric ${warn?'warn':''}`}><div><span>{title}</span><Icon name={icon} size={18}/></div><strong>{formatNumber(value)}</strong><small>{note}</small></div>;}
function Usage({label,used=0,max}: {label:string;used?:number;max:number}) {const percentage=Math.min(100,max>0?used/max*100:0);return <div className="usage"><div><span>{label}</span><strong>{formatNumber(used)}<small> / {formatNumber(max)}</small></strong></div><div className="usage-track" role="progressbar" aria-label={label} aria-valuenow={used} aria-valuemin={0} aria-valuemax={Math.max(max,used)}><span style={{width:`${percentage}%`}}/></div></div>;}
function CaseCard({testCase:c,executions}: {testCase:TestCase;executions:Record<string,unknown>[]}) {return <div className="case-card"><div className="case-top"><span className="trace-connector"/><div><code>{c.id}</code><h4>{c.title}</h4></div><Badge value={executions.length?String(executionResult(executions[executions.length-1]).status??'inconclusive'):'created'}>{executions.length?undefined:'尚未執行'}</Badge></div><div className="case-route"><span>{c.method}</span><code>{c.path}</code><small>{c.adapter}</small></div><div className="case-oracle"><strong>Oracle</strong><code>{c.oracle.kind}</code><span>{c.observation_mode==='instrumented_observation'?'含內部觀測':'外部觀測'}</span><span>{c.repetitions} 次驗證</span></div><details className="text-details"><summary>必要觀測與案例契約</summary><SafeText value={{required_observations:c.oracle.required_observations,allowed_statuses:c.oracle.allowed_statuses,expected_role:c.oracle.expected_role,preconditions:c.preconditions,side_effects:c.side_effects,cleanup:c.cleanup,source_digest:c.source_digest,threat_model_hash:c.threat_model_hash,hash:c.hash}}/></details></div>;}
function Findings({run,onEvidence,onUpdated}: {run:Run;onEvidence:(id:string)=>void;onUpdated?:(run:Run)=>void}) {
  const findings=run.findings??[];
  const [filter,setFilter]=useState('all');const filtered=filter==='all'?findings:findings.filter(f=>f.state===filter);
  return <><div className="finding-toolbar"><p>嚴重度與證據狀態分別記錄，尚待驗證的假設不會顯示為已證實。</p><label className="sr-only" htmlFor="finding-filter">篩選證據狀態</label><select id="finding-filter" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">全部證據狀態</option>{Object.entries(STATES).map(([key,label])=><option value={key} key={key}>{label}</option>)}</select></div>{filtered.length?filtered.map(f=><article className="finding-card" key={f.id}><div className="finding-header"><span className={`severity ${f.severity}`}>{SEVERITY[f.severity]??f.severity}</span><code>{f.id}</code><Badge value={f.state}>{STATES[f.state]??f.state}</Badge></div><h3>{f.title}</h3><p>{f.description}</p>{f.file&&<div className="finding-location"><Icon name="code" size={15}/><code>{f.file}{f.line?`:${f.line}`:''}</code>{f.cwe&&<span>{f.cwe}</span>}</div>}<div className="finding-links"><div><span>提出者</span>{f.agent_ids?.length?f.agent_ids.map(id=><code key={id}>{id}</code>):'未記錄'}</div><div><span>威脅</span>{f.threat_ids?.length?f.threat_ids.map(id=><code key={id}>{id}</code>):'未關聯'}</div><div><span>證據</span>{f.evidence_ids?.length?f.evidence_ids.map(id=><button type="button" className="evidence-link" key={id} onClick={()=>onEvidence(id)}>{short(id)}<Icon name="arrow" size={10}/></button>):'待補足'}</div></div><DecisionControl run={run} finding={f} onUpdated={onUpdated}/></article>):<Empty title={findings.length?'沒有符合篩選的發現':'目前沒有安全發現'}>請同時查看執行狀態、涵蓋範圍與驗證缺口；空白清單不等於安全保證。</Empty>}</>;
}

// Mirrors the backend decision rules: only a black-box execution of this run can
// count as counterevidence, a refutation needs a pass, and an observed violation
// is never decided away - it needs a linked retest.
function DecisionControl({run,finding,onUpdated}: {run:Run;finding:Finding;onUpdated?:(run:Run)=>void}) {
  const [decision,setDecision]=useState<'refuted'|'inconclusive'>('inconclusive');
  const [rationale,setRationale]=useState('');
  const [evidenceIds,setEvidenceIds]=useState<string[]>([]);
  const [threatIds,setThreatIds]=useState<string[]>([]);
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const applicable=finding.threat_ids.length?finding.threat_ids:threatIds;
  const executions=new Map((run.executions??[]).map(e=>[String(record(e).evidence_id??''),e]));
  const caseThreats=(evidenceId:string)=>new Set(run.cases.find(c=>c.id===String(record(executions.get(evidenceId)??{}).case_id??''))?.threat_ids??[]);
  const countsThreat=(evidenceId:string,threats:string[])=>threats.length?[...threats].some(t=>caseThreats(evidenceId).has(t)):false;
  const candidates=run.artifacts.map(record).filter(a=>a.producer==='blackbox-worker'&&!finding.evidence_ids.includes(String(a.id)));
  const needThreats=!finding.threat_ids.length;
  if(finding.state==='validated_dynamic')return <p className="field-hint">已觀測到違規的發現不能在此排除；請建立修補複測驗證修正。</p>;
  if(['running','cancelling'].includes(run.status)||!candidates.length&&!finding.decisions?.length)return null;
  async function decide(){setBusy(true);setError('');try{const next=await api<Run>(`/runs/${encodeURIComponent(run.id)}/findings/${encodeURIComponent(finding.id)}/decision`,{decision,rationale:rationale.trim(),evidence_ids:evidenceIds,threat_ids:finding.threat_ids.length?[]:threatIds});onUpdated?.(next);setRationale('');setEvidenceIds([]);setThreatIds([]);}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy(false);}}
  // Mirror the backend's refutation rules client-side: a refutation needs a cited
  // pass, and no execution testing these threats may have observed a violation.
  const observedFail=(run.executions??[]).some(e=>String(executionResult(e).status??'')==='fail'&&applicable.some(t=>caseThreats(String(record(e).evidence_id??'')).has(t)));
  const citedPass=evidenceIds.some(id=>String(executionResult(executions.get(id)??{}).status??'')==='pass');
  const refutedBlocked=decision==='refuted'&&(observedFail||!citedPass);
  const blocked=!rationale.trim()||!evidenceIds.length||(needThreats&&!threatIds.length)||refutedBlocked;
  return <details className="text-details finding-decision">
    <summary>證據裁決{finding.decisions?.length?` · 已記錄 ${finding.decisions.length} 項`:''}</summary>
    <p className="field-hint">只有本次執行中、與此發現威脅相關的黑箱執行紀錄可以當作反證；模型審查與掃描輸出只是來源，不能推翻自己。</p>
    {finding.decisions?.map((entry,i)=><p className="field-hint" key={i}>#{i+1} {entry.actor} 於 {date(entry.at)} 裁決為「{STATES[entry.decision]??entry.decision}」（原狀態：{STATES[entry.previous_state]??entry.previous_state}）；理由：{entry.rationale.slice(0,200)}{entry.rationale.length>200?'…':''}</p>)}
    <div className="form-grid"><Field label="裁決"><select value={decision} onChange={e=>setDecision(e.target.value as 'refuted'|'inconclusive')}><option value="inconclusive">尚無定論（證據不足）</option><option value="refuted">已排除（反證執行觀測到安全條件成立）</option></select></Field></div>
    <Field label="裁決理由（會存入證據紀錄）"><textarea value={rationale} onChange={e=>setRationale(e.target.value)} rows={2} maxLength={4000} placeholder="說明為什麼這些執行紀錄足以支持此裁決。"/></Field>
    {needThreats&&<fieldset className="retest-findings"><legend>此反證所測試的威脅（此發現尚未關聯威脅）</legend>{(run.threat_model?.threats??[]).map(t=><label key={t.id}><input type="checkbox" checked={threatIds.includes(t.id)} onChange={e=>{const next=e.target.checked?[...threatIds,t.id]:threatIds.filter(id=>id!==t.id);setThreatIds(next);setEvidenceIds(prev=>prev.filter(id=>countsThreat(id,next)));}}/><span>{t.title}<small>{t.id}</small></span></label>)}{!run.threat_model?.threats?.length&&<p className="field-hint">此執行沒有威脅模型可選擇。</p>}</fieldset>}
    <fieldset className="retest-findings"><legend>引用的黑箱執行證據</legend>{candidates.map(artifact=>{const id=String(artifact.id);const ex=executions.get(id);const status=String(executionResult(ex??{}).status??'inconclusive');const usable=countsThreat(id,applicable);return <label key={id} className={usable?'':'muted'}><input type="checkbox" checked={evidenceIds.includes(id)} disabled={!usable} onChange={e=>setEvidenceIds(e.target.checked?[...evidenceIds,id]:evidenceIds.filter(v=>v!==id))}/><span>{String(record(ex??{}).case_id??'未記錄案例')}<small>{short(id)} · {STATUS[status]??status}</small></span></label>;})}{!candidates.length&&<p className="field-hint">此執行沒有可引用的黑箱執行證據。</p>}{needThreats&&!threatIds.length&&<p className="field-hint">先選擇反證所測試的威脅，才會開放可用的執行證據。</p>}</fieldset>
    {decision==='refuted'&&observedFail&&<p className="field-hint">此執行已有測試這些威脅的案例觀測到違規，後端不會接受「已排除」；請改為「尚無定論」或以修補複測驗證。</p>}
    {decision==='refuted'&&!observedFail&&!citedPass&&<p className="field-hint">「已排除」需要至少一筆被引用執行觀測到安全條件成立（pass）。</p>}
    {error&&<p className="inline-warning" role="alert">{error}</p>}
    <button type="button" className="button secondary small" disabled={busy||blocked} onClick={()=>void decide()}>{busy?'記錄中…':'記錄證據裁決'}</button>
  </details>;
}

function EvidenceBrowser({run,focusId}: {run:Run;focusId:string}) {
  const [data,setData]=useState<Record<string,unknown>>({});
  const [loading,setLoading]=useState('');const [error,setError]=useState('');
  const artifacts=run.artifacts.map(record);
  const load=useCallback(async(id:string)=>{setLoading(id);setError('');try{const result=await api<unknown>(`/runs/${encodeURIComponent(run.id)}/evidence/${encodeURIComponent(id)}`);setData(prev=>({...prev,[id]:result}));}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setLoading('');}},[run.id]);
  useEffect(()=>{if(focusId&&artifacts.some(a=>a.id===focusId)){void load(focusId);window.setTimeout(()=>document.getElementById(`artifact-${focusId}`)?.scrollIntoView({behavior:'smooth',block:'center'}),80);}},[focusId,load]);
  if(!artifacts.length)return null;
  return <Panel title="可驗證的證據檔案" eyebrow="EVIDENCE REGISTER"><p className="panel-copy evidence-intro">開啟時由後端核對內容摘要；證據 ID 可連回發現與執行紀錄。</p>{error&&<div className="inline-warning" role="alert">{error}</div>}<div className="artifact-list">{artifacts.map(artifact=>{const id=String(artifact.id);return <div className={`artifact ${id===focusId?'highlight':''}`} id={`artifact-${id}`} key={id}><div className="artifact-top"><Icon name="file" size={18}/><div><strong>{String(artifact.producer??'證據')}</strong><code>{id}</code></div><button type="button" className="button secondary small" disabled={!!loading} onClick={()=>void load(id)}>{loading===id?'核對中…':id in data?'重新核對':'檢視證據'}</button></div><div className="artifact-hash"><span>SHA-256</span><code>{String(artifact.sha256??'未記錄')}</code></div>{id in data&&<SafeText value={data[id]}/>}</div>;})}</div></Panel>;
}

function AuthProfilesEditor({profiles,onChange}: {profiles:AuthProfile[];onChange:(profiles:AuthProfile[])=>void}) {
  function update(index:number,patch:Partial<AuthProfile>) {onChange(profiles.map((p,i)=>i===index?{...p,...patch}:p));}
  return <details className="text-details" style={{marginTop:0,marginBottom:23}}><summary>測試身分與憑證（可選）</summary><p className="field-hint">用獨立測試帳號驗證權限邊界。僅填憑證環境變數名稱；角色宣告本身不等於角色已獲驗證。</p>{profiles.map((profile,index)=><div className="auth-profile" key={index}><div className="auth-profile-top"><strong>測試身分 {index+1}</strong><button type="button" className="icon-button" aria-label={`移除測試身分 ${index+1}`} onClick={()=>onChange(profiles.filter((_,i)=>i!==index))}><Icon name="close" size={15}/></button></div><div className="form-grid"><Field label="身分識別"><input value={profile.id} onChange={e=>update(index,{id:e.target.value})} placeholder="tenant-a-user"/></Field><Field label="預期角色"><input value={profile.role} onChange={e=>update(index,{role:e.target.value})} placeholder="user"/></Field><Field label="憑證的環境變數名稱"><input value={profile.credential_env} onChange={e=>update(index,{credential_env:e.target.value})} placeholder="VIBEAUDIT_USER_A_TOKEN" autoComplete="off"/></Field><Field label="HTTP Header 名稱"><input value={profile.header} onChange={e=>update(index,{header:e.target.value})} placeholder="Authorization"/></Field><Field label="憑證前綴"><input value={profile.scheme} onChange={e=>update(index,{scheme:e.target.value})} placeholder="Bearer；不需前綴時可留白"/></Field></div><div className="check-options"><label><input type="checkbox" checked={profile.model_selectable===true} onChange={e=>update(index,{model_selectable:e.target.checked})}/>允許模型設計的案例使用此身分</label></div><p className="field-hint">預設不允許；高權限帳號請勿勾選。操作者自填的案例不受此限。</p></div>)}<button type="button" className="button secondary small" style={{marginTop:12}} onClick={()=>onChange([...profiles,{id:`identity-${profiles.length+1}`,role:'user',credential_env:'',header:'Authorization',scheme:'Bearer'}])}><Icon name="plus" size={14}/>新增測試身分</button></details>;
}

const demoModels=():ModelProfile[]=>['commander','reviewer-a','reviewer-b','reviewer-c'].map((id,i)=>({id,role:i===0?'commander':'reviewer',provider:'demo',model_id:`synthetic-${i===0?'commander':i}`,family:`synthetic-${i}`,endpoint:'',credential_env:'',temperature:0,max_output_tokens:3000}));
const defaultBudget:Budget={max_seconds:600,max_requests:30,max_model_calls:20,max_tokens:50000};
function CreateForm({onCreate,busy,connected}: {onCreate:(input:RunInput)=>Promise<void>;busy:boolean;connected:boolean}) {
  const [mode,setMode]=useState<'demo'|'live'>('demo');const [name,setName]=useState('我的第一個安全評估');
  const [source,setSource]=useState('');const [target,setTarget]=useState('');const [deployment,setDeployment]=useState('');
  const [dataPolicy,setDataPolicy]=useState<'local_only'|'cloud_allowed'>('local_only');const [origins,setOrigins]=useState('');const [ips,setIps]=useState('');const [requests,setRequests]=useState('');const [notes,setNotes]=useState('');const [caseText,setCaseText]=useState('');
  const [budget,setBudget]=useState<Budget>(defaultBudget);const [models,setModels]=useState<ModelProfile[]>(demoModels);
  const [authProfiles,setAuthProfiles]=useState<AuthProfile[]>([]);
  const [extensions,setExtensions]=useState<RunExtensions>(defaultExtensions);
  const [specialRole,setSpecialRole]=useState<ModelProfile['role']>('architecture_mapper');
  const [formError,setFormError]=useState('');const [probe,setProbe]=useState<Record<string,{pending:boolean;message:string;ok?:boolean}>>({});
  const split=(v:string)=>v.split(/[\s,]+/).map(s=>s.trim()).filter(Boolean);
  const validation=useMemo(()=>{
    const errors:string[]=[];if(!name.trim())errors.push('請填寫評估名稱。');
    if(Object.values(budget).some(v=>!Number.isFinite(v)||v<1||!Number.isInteger(v)))errors.push('預算須為大於 0 的整數。');
    if(budget.max_seconds<10||budget.max_seconds>14400)errors.push('時間上限須介於 10 與 14,400 秒。');
    if(budget.max_requests>10000||budget.max_model_calls>500)errors.push('請求上限不可超過 10,000 次，模型呼叫上限不可超過 500 次。');
    if(budget.max_tokens<1000||budget.max_tokens>2000000)errors.push('Token 預算須介於 1,000 與 2,000,000。');
    if(mode==='live'){
      if(!/^(?:[A-Za-z]:[\\/]|\/)/.test(source.trim()))errors.push('來源程式請使用本機絕對路徑。');
      try{const u=new URL(target);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.hash)throw new Error();}catch{errors.push('請設定有效的 HTTP(S) staging URL，不含帳密或 fragment。');}
      if(!deployment.trim())errors.push('請填寫部署識別，以對應本次測試版本。');
      if(!split(ips).length)errors.push('請明確列出允許測試的目標 IP。');
      if(requests.split('\n').filter(s=>s.trim()).some(s=>!/^(GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\s+\/\S*$/.test(s.trim())))errors.push('允許的請求每行填寫 GET /path 或 POST /path，方法與路徑須精確。');
      if(models.some(m=>!m.model_id.trim()||!m.family.trim()||!m.endpoint.trim()))errors.push('所有 Agent 都需要模型 ID、家族和 API 端點。');
      if(models.some(m=>m.provider==='demo'))errors.push('實際評估不能使用合成模型。');
      if(models.some(m=>{try{const u=new URL(m.endpoint);return !['http:','https:'].includes(u.protocol)||!!u.username||!!u.password;}catch{return true;}}))errors.push('模型端點必須為有效的 HTTP(S) URL，不能內含金鑰。');
      if(dataPolicy==='cloud_allowed'&&!split(origins).length)errors.push('允許雲端時，請明確填寫模型 origin allowlist。');
      if(models.some(m=>m.credential_env&&!/^VIBEAUDIT_[A-Z0-9_]+$/.test(m.credential_env)))errors.push('憑證欄位須填 VIBEAUDIT_* 格式的環境變數名稱，不能填 API 金鑰。');
      if(new Set(models.filter(m=>m.role==='reviewer').map(m=>m.family.trim().toLowerCase())).size!==3)errors.push('三位審查員需要三個不同的模型家族。');
      if(new Set(models.filter(m=>m.role==='reviewer').map(m=>[m.provider,m.model_id,m.endpoint].join('|'))).size!==3)errors.push('三位審查員需要三種不同的模型配置。');
      if(models.some(m=>!Number.isInteger(m.max_output_tokens)||m.max_output_tokens<256||m.max_output_tokens>16000))errors.push('單次模型輸出須介於 256 與 16,000 tokens。');if(models.some(m=>m.temperature!==null&&(!Number.isFinite(m.temperature)||m.temperature<0||m.temperature>2)))errors.push('Temperature 須介於 0 與 2，或留空使用模型預設值。');
      if(authProfiles.some(p=>!p.id.trim()||!p.role.trim()||!/^VIBEAUDIT_[A-Z0-9_]+$/.test(p.credential_env)))errors.push('測試身分需要識別、角色與 VIBEAUDIT_* 憑證環境變數名稱。');
      if(new Set(authProfiles.map(p=>p.id)).size!==authProfiles.length)errors.push('測試身分的識別不能重複。');
      if(caseText.trim()){try{if(!Array.isArray(JSON.parse(caseText)))throw new Error();}catch{errors.push('自訂案例必須是 JSON 陣列。');}}
    }return errors;
  },[name,budget,mode,source,target,deployment,ips,requests,models,dataPolicy,origins,caseText,authProfiles]);
  function changeMode(next:'demo'|'live'){setMode(next);setProbe({});setModels(next==='demo'?demoModels():demoModels().map(m=>({...m,provider:'openai_compatible',model_id:'',family:'',endpoint:'http://127.0.0.1:11434/v1'})));}
  function updateModel(i:number,patch:Partial<ModelProfile>){setModels(prev=>prev.map((m,index)=>index===i?{...m,...patch}:m));setProbe(prev=>({...prev,[models[i].id]:{pending:false,message:''}}));}
  function changeProvider(i:number,provider:Provider){const defaults:Partial<Record<Provider,Partial<ModelProfile>>>={openai:{endpoint:'https://api.openai.com/v1',credential_env:'VIBEAUDIT_OPENAI_API_KEY',family:'gpt'},anthropic:{endpoint:'https://api.anthropic.com',credential_env:'VIBEAUDIT_ANTHROPIC_API_KEY',family:'claude'},nvidia_nim:{endpoint:'http://127.0.0.1:8001/v1',credential_env:'',family:'nemotron'},openai_compatible:{endpoint:'http://127.0.0.1:11434/v1',credential_env:'',family:''}};updateModel(i,{provider,model_id:'',...defaults[provider]});}
  // The origins field is disabled under local_only; stale cloud entries must not narrow the loopback check.
  function modelOrigins(){return dataPolicy==='local_only'?[]:split(origins);}
  async function probeModel(model:ModelProfile){setProbe(prev=>({...prev,[model.id]:{pending:true,message:'檢查端點與能力…'}}));try{const result=await api<Record<string,unknown>>('/models/probe',{profile:model,data_policy:dataPolicy,allowed_model_origins:modelOrigins(),budget});const ok=result.available===false||result.ok===false||result.status==='failed'?false:true;setProbe(prev=>({...prev,[model.id]:{pending:false,ok,message:stringify(result)}}));}catch(e){setProbe(prev=>({...prev,[model.id]:{pending:false,ok:false,message:e instanceof Error?e.message:String(e)}}));}}
  function configuration():RunInput {
    return {...extensions,schema_version:2,name:name.trim(),mode,source_path:mode==='demo'?'':source.trim(),deployment_id:mode==='demo'?'':deployment.trim(),target_url:mode==='demo'?'':target.trim(),data_policy:mode==='demo'?'local_only':dataPolicy,allowed_model_origins:mode==='demo'?[]:modelOrigins(),allowed_target_ips:mode==='demo'?[]:split(ips),allowed_requests:mode==='demo'?[]:requests.split('\n').filter(s=>s.trim()).map(s=>{const [method,path]=s.trim().split(/\s+/);return {method:method as RunInput['allowed_requests'][number]['method'],path};}),budget,models,auth_profiles:mode==='demo'?[]:authProfiles,notes,parent_run_id:null,cases:mode==='live'&&caseText.trim()?JSON.parse(caseText) as TestCase[]:[]};
  }
  function loadConfiguration(input:RunInput) {
    setName(input.name);setMode(input.mode);setSource(input.source_path);setTarget(input.target_url);setDeployment(input.deployment_id);setDataPolicy(input.data_policy);setOrigins(input.allowed_model_origins.join('\n'));setIps(input.allowed_target_ips.join('\n'));setRequests(input.allowed_requests.map(r=>r.method+' '+r.path).join('\n'));setBudget(input.budget);setModels(input.models.length?input.models:demoModels());setAuthProfiles(input.auth_profiles);setNotes(input.notes);setCaseText(input.cases.length?JSON.stringify(input.cases,null,2):'');setExtensions({...defaultExtensions(),requirements:input.requirements??[],runtime_profile:input.runtime_profile??'default',fixture_profile:input.fixture_profile??null,static_tools:input.static_tools??['semgrep','osv','gitleaks'],deployment_header:input.deployment_header??null});setProbe({});setFormError('');
  }
  async function submit(e:FormEvent){e.preventDefault();setFormError('');if(validation.length){setFormError(validation.join(' '));return;}try{await onCreate(configuration());}catch{/* Shared API notice retains the failure. */}}

  return <><div className="page-heading"><div><div className="eyebrow">NEW ASSESSMENT</div><h1>建立一個有邊界的評估</h1><p>設定目標、審查模型與執行預算。系統會依序檢查階段條件。</p></div><span className="local-label"><Icon name="lock" size={16}/>本地執行</span></div><form onSubmit={submit} className="create-form"><div className="create-main"><ProjectControls configuration={configuration} onLoad={loadConfiguration}/><Panel title="評估方式" eyebrow="01 / WORKSPACE"><div className="mode-switch">{(['demo','live'] as const).map(value=><button type="button" key={value} className={mode===value?'mode-option selected':'mode-option'} onClick={()=>changeMode(value)}><span className="mode-option-top"><Icon name={value==='demo'?'chip':'shield'}/><span className="radio-dot"/></span><strong>{value==='demo'?'合成示範':'實際評估'}</strong><p>{value==='demo'?'不用金鑰。在本地 fixture 上走完驗證流程。':'使用真實模型審查程式，測試你提供的 staging。'}</p></button>)}</div><Field label="評估名稱"><input value={name} onChange={e=>setName(e.target.value)} maxLength={140} placeholder="例如：客服 Agent 上線前評估" required/></Field>{mode==='demo'&&<div className="notice subtle compact"><Icon name="file" size={17}/><p>示範會真正建立並啟動後端流程，但所有模型輸出與情境都是合成資料。</p></div>}</Panel>
      <Panel title="來源與測試範圍" eyebrow="02 / AUTHORIZED SCOPE"><fieldset disabled={mode==='demo'} className={mode==='demo'?'disabled-scope':''}><Field label="本機程式來源" hint="只讀取程式，不在主機上執行來源專案。"><input value={source} onChange={e=>setSource(e.target.value)} placeholder="C:\projects\my-app 或 /home/me/my-app"/></Field><div className="form-grid"><Field label="隔離 staging URL"><input value={target} onChange={e=>setTarget(e.target.value)} placeholder="http://127.0.0.1:8080"/></Field><Field label="部署識別" hint="例如 commit SHA 或部署版本。"><input value={deployment} onChange={e=>setDeployment(e.target.value)} placeholder="staging-2026-09-24"/></Field></div><Field label="允許的目標 IP" hint="逗號或換行分隔；重新導向不會自動放行。"><textarea value={ips} onChange={e=>setIps(e.target.value)} rows={2} placeholder="127.0.0.1"/></Field><Field label="精確允許的請求" hint="每行一組方法＋路徑。留白會阻擋全部黑箱請求；不代表允許全站。POST 只用於可重置的隔離環境。"><textarea value={requests} onChange={e=>setRequests(e.target.value)} rows={3} placeholder={"GET /api/profile\nPOST /chat"} spellCheck={false}/></Field></fieldset>{mode==='demo'&&<p className="field-hint">示範模式不需要目標、路徑或部署設定。</p>}</Panel>
      <Panel title="指揮官與審查員" eyebrow="03 / INDEPENDENT REVIEW"><div className="model-intro"><p>三位審查員各自處理相同核心問題，封存初審後再整合證據。不同模型不保證消除共同偏誤。</p>{mode==='demo'&&<Badge value="demo">全部為合成模型</Badge>}</div>{mode==='live'&&<div className="policy-fields"><Field label="程式資料政策"><select value={dataPolicy} onChange={e=>{const value=e.target.value as 'local_only'|'cloud_allowed';setDataPolicy(value);setProbe({});if(value==='local_only')setModels(prev=>prev.map(m=>m.provider==='openai'||m.provider==='anthropic'?{...m,provider:'openai_compatible',model_id:'',family:'',endpoint:'http://127.0.0.1:11434/v1',credential_env:''}:m));}}><option value="local_only">僅本地模型</option><option value="cloud_allowed">允許指定雲端模型</option></select></Field><Field label="允許的模型 origins" hint="包含通訊協定、主機與埠；不包含 /v1 等路徑。"><textarea disabled={dataPolicy==='local_only'} value={origins} onChange={e=>setOrigins(e.target.value)} rows={2} placeholder={dataPolicy==='local_only'?'本地政策由後端驗證端點':'https://api.openai.com\nhttps://api.anthropic.com'}/></Field></div>}<div className="model-configs">{models.map((model,i)=><details className="model-config" key={model.id} open={mode==='live'}><summary><span className={`agent-avatar a${i}`}><Icon name={i===0?'shield':'chip'} size={18}/></span><div><strong>{ROLE_LABELS[model.role]}</strong><small>{PROVIDERS[model.provider]} · {model.model_id||'尚未設定模型'}</small></div><code>{model.id}</code><Icon name="chevron" size={15}/></summary><fieldset disabled={mode==='demo'}><div className="form-grid"><Field label="模型供應商"><select value={model.provider} onChange={e=>changeProvider(i,e.target.value as Provider)}>{mode==='demo'?<option value="demo">本地合成示範</option>:Object.entries(PROVIDERS).filter(([p])=>p!=='demo').map(([p,label])=><option key={p} value={p} disabled={dataPolicy==='local_only'&&['openai','anthropic'].includes(p)}>{label}</option>)}</select></Field><Field label="模型 ID"><input value={model.model_id} onChange={e=>updateModel(i,{model_id:e.target.value})} placeholder="填入端點提供的精確模型 ID"/></Field><Field label="模型家族"><input value={model.family} onChange={e=>updateModel(i,{family:e.target.value})} placeholder="例如 claude / gpt / nemotron"/></Field><Field label="API 端點"><input value={model.endpoint} onChange={e=>updateModel(i,{endpoint:e.target.value})} placeholder="http://127.0.0.1:11434/v1"/></Field><Field label="金鑰的環境變數名稱" hint="只填名稱；請勿貼上實際金鑰。金鑰只會送到操作者在 VIBEAUDIT_MODEL_CREDENTIAL_ORIGINS 綁定的 origin。"><input value={model.credential_env} onChange={e=>updateModel(i,{credential_env:e.target.value})} autoComplete="off" spellCheck={false} placeholder="例如 VIBEAUDIT_OPENAI_API_KEY；本地可空白"/></Field><Field label="單次輸出 token 上限"><input type="number" min={256} max={16000} value={model.max_output_tokens} onChange={e=>updateModel(i,{max_output_tokens:Number(e.target.value)})}/></Field><Field label="Temperature" hint="留空使用模型預設值；部分推理模型只接受預設值。"><input type="number" min={0} max={2} step={0.1} value={model.temperature??''} onChange={e=>updateModel(i,{temperature:e.target.value===''?null:Number(e.target.value)})} placeholder="模型預設"/></Field></div>{mode==='live'&&<button className="button secondary small" type="button" disabled={!connected||probe[model.id]?.pending||!model.model_id||!model.endpoint} onClick={()=>void probeModel(model)}><Icon name="pulse" size={14}/>{probe[model.id]?.pending?'檢查中…':'檢查模型連線與能力'}</button>}</fieldset>{mode==='live'&&<ModelPresetControls model={model} onLoad={profile=>updateModel(i,profile)}/>} {model.role!=='commander'&&model.role!=='reviewer'&&<button type="button" className="button secondary small" onClick={()=>setModels(models.filter(m=>m.id!==model.id))}>移除此專責 Agent</button>}{probe[model.id]?.message&&<div className={`probe-result ${probe[model.id].ok===false?'error':''}`} role="status"><SafeText value={probe[model.id].message}/></div>}</details>)}</div>{mode==='live'&&<div className="workspace-actions"><label className="field"><span>選配專責 Agent</span><select value={specialRole} onChange={e=>setSpecialRole(e.target.value as ModelProfile['role'])}>{Object.entries(ROLE_LABELS).filter(([role])=>!['commander','reviewer'].includes(role)).map(([role,label])=><option key={role} value={role}>{label}</option>)}</select></label><button type="button" className="button secondary small" disabled={models.some(m=>m.role===specialRole)} onClick={()=>setModels([...models,{id:specialRole,role:specialRole,provider:'openai_compatible',model_id:'',family:'',endpoint:'',credential_env:'',temperature:0,max_output_tokens:3000}])}>新增專責 Agent</button></div>}{mode==='live'&&<p className="field-hint">檢查模型可能產生供應商用量。模型探測結果不代表資安偵測品質；後端仍會執行正式預檢。</p>}</Panel>
      <ExecutionSettings value={extensions} onChange={setExtensions} disabled={mode==='demo'}/><Panel title="補充需求" eyebrow="04 / CONTEXT">{mode==='live'&&<AuthProfilesEditor profiles={authProfiles} onChange={setAuthProfiles}/>}<Field label="評估備註" hint="業務安全條件、優先關注的功能，或目前已知限制。"><textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={3} placeholder="例如：不同租戶不能存取彼此的客服紀錄。"/></Field>{mode==='live'&&<details className="text-details"><summary>進階：提供具明確 oracle 的測試案例</summary><p className="field-hint">可貼上契約中的 Case JSON 陣列。後端會檢查威脅關聯、必要觀測、來源摘要與執行範圍；不完整案例不會自動通過。</p><label className="sr-only" htmlFor="case-json">自訂案例 JSON</label><textarea id="case-json" className="code-input" rows={8} value={caseText} onChange={e=>setCaseText(e.target.value)} placeholder="[]" spellCheck={false}/></details>}</Panel></div>
      <aside className="create-summary"><Panel title="執行預算" eyebrow="BOUND THE RUN"><div className="budget-fields">{([['max_seconds','時間上限','秒'],['max_requests','目標請求上限','次'],['max_model_calls','模型呼叫上限','次'],['max_tokens','模型 token 上限','tokens']] as const).map(([key,label,unit])=><Field label={label} key={key}><div className="input-unit"><input type="number" min={1} step={1} value={budget[key]} onChange={e=>setBudget({...budget,[key]:Number(e.target.value)})}/><span>{unit}</span></div></Field>)}</div><div className="summary-divider"/><div className="run-summary-row"><span>模式</span><strong>{mode==='demo'?'本地合成示範':'實際資安評估'}</strong></div><div className="run-summary-row"><span>審查小組</span><strong>1 指揮官 + 3 審查員</strong></div><div className="run-summary-row"><span>測試順序</span><strong>白箱 → 建模 → 黑箱</strong></div><div className="summary-divider"/><div className="summary-safety"><Icon name="lock" size={18}/><p>{mode==='demo'?'示範只使用本地合成情境，不會呼叫設定中的外部服務。':'限你擁有或已獲授權的隔離 staging。範圍、威脅與案例都通過閘門後，才發送測試請求。'}</p></div>{formError&&<div className="inline-warning" role="alert">{formError}</div>}<button type="submit" className="button primary create-submit" disabled={busy||!connected}>{busy?<><span className="spinner"/>正在建立…</>:<>建立並開始<Icon name="arrow" size={17}/></>}</button><p className="submit-note">超出預算或證據不足時，會保留缺口並停止相應操作。</p></Panel></aside>
    </form></>;
}
function Field({label,hint,children}: {label:string;hint?:string;children:ReactNode}) {return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function CapabilitiesView({capabilities,session}: {capabilities:Capabilities|null;session:Session|null}) {return <><div className="page-heading"><div><div className="eyebrow">HONEST CAPABILITIES</div><h1>工具與執行環境</h1><p>能力可用、受限或尚未實作，都由本地後端如實回報。</p></div><span className="local-label"><Icon name="chip" size={17}/>即時能力清單</span></div><div className="capabilities-grid">{capabilities?.tools.map(tool=><article className="capability-card" key={tool.id}><div><span className="tool-icon"><Icon name="chip"/></span><Badge value={tool.available?'completed':'blocked'}>{tool.available?'可使用':'尚不可使用'}</Badge></div><h3>{tool.id}</h3><p>{tool.detail}</p><code>{tool.status}</code></article>)}</div>{!capabilities?.tools?.length&&<Empty title="尚無工具清單">確認本地服務連線，然後更新執行環境。</Empty>}<div className="detail-columns"><Panel title="已知限制" eyebrow="LIMITATIONS"><ul className="limitations">{[...(session?.limitations??[]),...(capabilities?.limitations??[])].filter((v,i,a)=>a.indexOf(v)===i).map((text,i)=><li key={i}><Icon name="alert" size={16}/><span>{text}</span></li>)}</ul></Panel><Panel title="執行環境資訊" eyebrow="RUNTIME"><SafeText value={capabilities?.runtime??{}}/></Panel></div></>;}
